const MetricStatus = Object.freeze({
  MET: 'MET',
  BELOW_TARGET: 'BELOW_TARGET',
});

const OverallStatus = Object.freeze({
  ON_TRACK: 'ON_TRACK',
  NEEDS_ATTENTION: 'NEEDS_ATTENTION',
  NO_DATA: 'NO_DATA',
});

const ReviewFlag = Object.freeze({
  NONE: 'NONE',
  HUMAN_REVIEW: 'HUMAN_REVIEW',
});

const Priority = Object.freeze({
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW',
});

const RiskLevel = Object.freeze({
  HIGH: 'High',
  MEDIUM: 'Medium',
  LOW: 'Low',
});

const GapKey = Object.freeze({
  DIVERSE: 'diverse',
  WOMEN: 'women_owned',
  MINORITY: 'minority_owned',
});

function asEnum(value, allowed, fallback) {
  const list = Array.isArray(allowed) ? allowed : Object.values(allowed);
  return list.includes(value) ? value : fallback;
}

const suppliers = $('Get Suppliers').all().map((i) => i.json);
const transactions = $('Get Procurement Spend').all().map((i) => i.json);

function toBool(value) {
  if (typeof value === 'boolean') return value;
  const s = String(value ?? '').trim().toLowerCase();
  return ['yes', 'true', '1', 'y'].includes(s);
}

function toNumber(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const n = Number(String(value ?? '0').replace(/[$,%\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

function titleCaseRisk(value) {
  const s = String(value ?? RiskLevel.MEDIUM).trim().toLowerCase();
  if (s === 'high') return RiskLevel.HIGH;
  if (s === 'low') return RiskLevel.LOW;
  return RiskLevel.MEDIUM;
}

const supplierById = {};
for (const supplier of suppliers) {
  const id = String(supplier.supplier_id ?? '').trim();
  if (!id) continue;
  supplierById[id] = supplier;
}

if (!transactions.length) {
  return [
    {
      json: {
        transaction_id: '',
        date: '',
        supplier_id: '',
        supplier_name: '',
        category: 'Uncategorized',
        business_unit: 'Unknown',
        amount: 0,
        diverse: false,
        women_owned: false,
        minority_owned: false,
        esg_score: 0,
        risk_level: RiskLevel.MEDIUM,
        unmatched_supplier: true,
        _empty_input: true,
      },
    },
  ];
}

return transactions.map((tx) => {
  const supplierId = String(tx.supplier_id ?? '').trim();
  const supplier = supplierById[supplierId] || {};
  const esgScore = toNumber(supplier.esg_score);

  return {
    json: {
      transaction_id: tx.transaction_id,
      date: tx.date,
      supplier_id: supplierId,
      supplier_name: supplier.supplier_name || 'Unknown Supplier',
      category: String(tx.category || supplier.category || 'Uncategorized').trim(),
      business_unit: tx.business_unit || 'Unknown',
      amount: toNumber(tx.amount),
      diverse: toBool(supplier.diverse),
      women_owned: toBool(supplier.women_owned),
      minority_owned: toBool(supplier.minority_owned),
      esg_score: esgScore,
      risk_level: titleCaseRisk(supplier.risk_level),
      unmatched_supplier: !supplier.supplier_id,
    },
  };
});

const MetricStatus = Object.freeze({
  MET: 'MET',
  BELOW_TARGET: 'BELOW_TARGET',
});

const OverallStatus = Object.freeze({
  ON_TRACK: 'ON_TRACK',
  NEEDS_ATTENTION: 'NEEDS_ATTENTION',
  NO_DATA: 'NO_DATA',
});

const ReviewFlag = Object.freeze({
  NONE: 'NONE',
  HUMAN_REVIEW: 'HUMAN_REVIEW',
});

const Priority = Object.freeze({
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW',
});

const RiskLevel = Object.freeze({
  HIGH: 'High',
  MEDIUM: 'Medium',
  LOW: 'Low',
});

const GapKey = Object.freeze({
  DIVERSE: 'diverse',
  WOMEN: 'women_owned',
  MINORITY: 'minority_owned',
});

function asEnum(value, allowed, fallback) {
  const list = Array.isArray(allowed) ? allowed : Object.values(allowed);
  return list.includes(value) ? value : fallback;
}

const rows = $input.all().map((i) => i.json);
const targetRows = $('Get Targets').all().map((i) => i.json);
const supplierRows = $('Get Suppliers').all().map((i) => i.json);

function toNumber(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const n = Number(String(value ?? '0').replace(/[$,%\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
}

function parseTarget(metric, raw) {
  const s = String(raw ?? '').trim();
  const n = toNumber(s);
  const key = String(metric ?? '').toLowerCase();
  if (key.includes('rebalance')) {
    if (s.includes('%') || n > 1) return n / 100;
    return n;
  }
  if (key.includes('score') || key.includes('threshold') || key.includes('minimum')) {
    return n;
  }
  if (s.includes('%') || n > 1) return n / 100;
  return n;
}

function pct(part, total) {
  return total > 0 ? part / total : 0;
}

function roundPct(value) {
  return Math.round(value * 1000) / 10;
}

function money(value) {
  return Math.round(value * 100) / 100;
}

let period = `YTD ${new Date().getFullYear()}`;
let companyName = 'Your Company';
try {
  const cfg = $('Set Config').first().json;
  period = String(cfg.period || period);
  companyName = String(cfg.company_name || companyName);
} catch (e) {}

const targetMap = {};
for (const row of targetRows) {
  const key = String(row.metric ?? row.Metric ?? '').trim().toLowerCase();
  if (!key) continue;
  targetMap[key] = row.target ?? row.Target ?? row.value;
}

const diverseTarget = parseTarget('diverse_spend', targetMap.diverse_spend ?? '20%');
const womenTarget = parseTarget('women_owned_spend', targetMap.women_owned_spend ?? '10%');
const minorityTarget = parseTarget('minority_owned_spend', targetMap.minority_owned_spend ?? '8%');
const esgTarget = parseTarget('esg_spend', targetMap.esg_spend ?? '60%');
const minEsgScore = parseTarget('minimum_esg_score', targetMap.minimum_esg_score ?? 70);
const highImpactThreshold = toNumber(targetMap.high_impact_threshold ?? 500000) || 500000;
const maxRebalancePct = parseTarget('max_rebalance_pct', targetMap.max_rebalance_pct ?? '15%') || 0.15;

const seenSupplierIds = {};
let duplicateSupplierCount = 0;
for (const supplier of supplierRows) {
  const id = String(supplier.supplier_id ?? '').trim();
  if (!id) continue;
  if (seenSupplierIds[id]) duplicateSupplierCount += 1;
  seenSupplierIds[id] = true;
}

let totalSpend = 0;
let diverseSpend = 0;
let womenSpend = 0;
let minoritySpend = 0;
let esgSpend = 0;
let unmatchedCount = 0;
let unmatchedSpend = 0;
let skippedNonPositive = 0;

const supplierMap = {};
const categoryMap = {};
const emptyInput = rows.length === 1 && rows[0]._empty_input;

for (const row of rows) {
  if (row._empty_input) continue;
  const amount = toNumber(row.amount);
  if (amount <= 0) {
    skippedNonPositive += 1;
    continue;
  }
  if (row.unmatched_supplier) {
    unmatchedCount += 1;
    unmatchedSpend += amount;
    continue;
  }

  totalSpend += amount;
  if (row.diverse) diverseSpend += amount;
  if (row.women_owned) womenSpend += amount;
  if (row.minority_owned) minoritySpend += amount;
  if (toNumber(row.esg_score) >= minEsgScore) esgSpend += amount;

  const sid = row.supplier_id;
  if (!supplierMap[sid]) {
    supplierMap[sid] = {
      supplier_id: sid,
      supplier_name: row.supplier_name,
      category: row.category,
      diverse: !!row.diverse,
      women_owned: !!row.women_owned,
      minority_owned: !!row.minority_owned,
      esg_score: toNumber(row.esg_score),
      risk_level: asEnum(row.risk_level, RiskLevel, RiskLevel.MEDIUM),
      spend: 0,
    };
  }
  supplierMap[sid].spend += amount;

  const cat = row.category || 'Uncategorized';
  if (!categoryMap[cat]) {
    categoryMap[cat] = {
      category: cat,
      total_spend: 0,
      diverse_spend: 0,
      women_owned_spend: 0,
      minority_owned_spend: 0,
      esg_spend: 0,
      non_diverse_spend: 0,
    };
  }
  categoryMap[cat].total_spend += amount;
  if (row.diverse) categoryMap[cat].diverse_spend += amount;
  else categoryMap[cat].non_diverse_spend += amount;
  if (row.women_owned) categoryMap[cat].women_owned_spend += amount;
  if (row.minority_owned) categoryMap[cat].minority_owned_spend += amount;
  if (toNumber(row.esg_score) >= minEsgScore) categoryMap[cat].esg_spend += amount;
}

function metricBlock(label, actualSpend, targetPct) {
  const actualPct = pct(actualSpend, totalSpend);
  const gapPct = targetPct - actualPct;
  const status =
    totalSpend <= 0
      ? MetricStatus.BELOW_TARGET
      : actualPct + 0.0005 >= targetPct
        ? MetricStatus.MET
        : MetricStatus.BELOW_TARGET;
  return {
    label,
    actual_spend: money(actualSpend),
    actual_pct: actualPct,
    actual_pct_points: roundPct(actualPct),
    actual_pct_display: `${roundPct(actualPct)}%`,
    target_pct: targetPct,
    target_pct_points: roundPct(targetPct),
    target_pct_display: `${roundPct(targetPct)}%`,
    gap_pct: gapPct,
    gap_pct_display: `${roundPct(Math.abs(gapPct))}%`,
    gap_spend: money(gapPct * totalSpend),
    status,
  };
}

const metrics = {
  diverse: metricBlock('Diverse Spend', diverseSpend, diverseTarget),
  women_owned: metricBlock('Women-Owned Spend', womenSpend, womenTarget),
  minority_owned: metricBlock('Minority-Owned Spend', minoritySpend, minorityTarget),
  esg: metricBlock('ESG Qualified Spend', esgSpend, esgTarget),
};

const noData = totalSpend <= 0;
const allTargetsMet = !noData && Object.values(metrics).every((m) => m.status === MetricStatus.MET);
const overallStatus = noData
  ? OverallStatus.NO_DATA
  : allTargetsMet
    ? OverallStatus.ON_TRACK
    : OverallStatus.NEEDS_ATTENTION;

const missed = Object.values(metrics)
  .filter((m) => m.status === MetricStatus.BELOW_TARGET)
  .map((m) => m.label);

const supplierSpend = Object.values(supplierMap)
  .map((s) => ({
    ...s,
    spend: money(s.spend),
    spend_pct: pct(s.spend, totalSpend),
    esg_qualified: s.esg_score >= minEsgScore,
  }))
  .sort((a, b) => b.spend - a.spend);

const categorySpend = Object.values(categoryMap)
  .map((c) => {
    const inCat = Object.values(supplierMap).filter((s) => s.category === c.category);
    const topNonDiverse = inCat
      .filter((s) => !s.diverse && s.risk_level !== RiskLevel.HIGH)
      .sort((a, b) => b.spend - a.spend)[0];
    const topAny = [...inCat].sort((a, b) => b.spend - a.spend)[0];
    return {
      ...c,
      total_spend: money(c.total_spend),
      diverse_spend: money(c.diverse_spend),
      diverse_pct: pct(c.diverse_spend, c.total_spend),
      women_owned_spend: money(c.women_owned_spend),
      minority_owned_spend: money(c.minority_owned_spend),
      esg_spend: money(c.esg_spend),
      non_diverse_spend: money(c.non_diverse_spend),
      largest_non_diverse_supplier: topNonDiverse
        ? {
            supplier_id: topNonDiverse.supplier_id,
            supplier_name: topNonDiverse.supplier_name,
            spend: money(topNonDiverse.spend),
          }
        : null,
      top_supplier_share: topAny ? pct(topAny.spend, c.total_spend) : 0,
    };
  })
  .sort((a, b) => b.total_spend - a.total_spend);

return [
  {
    json: {
      run_date: new Date().toISOString().slice(0, 10),
      period,
      company_name: companyName,
      transaction_count: emptyInput ? 0 : rows.length,
      supplier_count: supplierSpend.length,
      unmatched_count: unmatchedCount,
      unmatched_spend: money(unmatchedSpend),
      skipped_non_positive: skippedNonPositive,
      duplicate_supplier_count: duplicateSupplierCount,
      total_spend: money(totalSpend),
      min_esg_score: minEsgScore,
      high_impact_threshold: highImpactThreshold,
      max_rebalance_pct: maxRebalancePct,
      metrics,
      missed_targets: missed,
      all_targets_met: allTargetsMet,
      overall_status: overallStatus,
      supplier_spend: supplierSpend,
      category_spend: categorySpend,
      recommendations: [],
      review_required: false,
      review_flag: ReviewFlag.NONE,
      priority: Priority.MEDIUM,
    },
  },
];

const MetricStatus = Object.freeze({
  MET: 'MET',
  BELOW_TARGET: 'BELOW_TARGET',
});

const OverallStatus = Object.freeze({
  ON_TRACK: 'ON_TRACK',
  NEEDS_ATTENTION: 'NEEDS_ATTENTION',
  NO_DATA: 'NO_DATA',
});

const ReviewFlag = Object.freeze({
  NONE: 'NONE',
  HUMAN_REVIEW: 'HUMAN_REVIEW',
});

const Priority = Object.freeze({
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW',
});

const RiskLevel = Object.freeze({
  HIGH: 'High',
  MEDIUM: 'Medium',
  LOW: 'Low',
});

const GapKey = Object.freeze({
  DIVERSE: 'diverse',
  WOMEN: 'women_owned',
  MINORITY: 'minority_owned',
});

function asEnum(value, allowed, fallback) {
  const list = Array.isArray(allowed) ? allowed : Object.values(allowed);
  return list.includes(value) ? value : fallback;
}

const data = $input.first().json;
const suppliers = data.supplier_spend || [];
const categories = data.category_spend || [];
const minEsg = data.min_esg_score || 70;
const diverseTarget = data.metrics?.diverse?.target_pct ?? 0.2;
const maxCategoryShare = 0.25;

function gapSpend(metrics, key) {
  return Math.max(0, Number(metrics?.[key]?.gap_spend || 0));
}

function helpsGap(supplier, key) {
  if (key === GapKey.DIVERSE) return !!supplier.diverse;
  if (key === GapKey.WOMEN) return !!supplier.women_owned;
  if (key === GapKey.MINORITY) return !!supplier.minority_owned;
  return false;
}

function scoreCandidate(supplier, metrics) {
  let score = 0;
  score += helpsGap(supplier, GapKey.DIVERSE) ? gapSpend(metrics, GapKey.DIVERSE) : 0;
  score += helpsGap(supplier, GapKey.WOMEN) ? gapSpend(metrics, GapKey.WOMEN) : 0;
  score += helpsGap(supplier, GapKey.MINORITY) ? gapSpend(metrics, GapKey.MINORITY) : 0;
  if (supplier.underused) score *= 1.15;
  score += Number(supplier.esg_score || 0) * 100;
  return score;
}

const categoryGaps = categories
  .map((c) => {
    const diverseGapSpend = Math.max(0, c.total_spend * diverseTarget - c.diverse_spend);
    const shiftable = c.non_diverse_spend;
    const potentialOpportunity = Math.round(
      Math.min(shiftable * 0.2, diverseGapSpend || shiftable * 0.15),
    );
    return {
      category: c.category,
      current_spend: c.total_spend,
      diverse_spend: c.diverse_spend,
      diverse_pct_display: `${Math.round((c.diverse_pct || 0) * 1000) / 10}%`,
      non_diverse_spend: c.non_diverse_spend,
      potential_opportunity: potentialOpportunity,
      shift_from: c.largest_non_diverse_supplier || null,
      top_supplier_share: c.top_supplier_share || 0,
    };
  })
  .filter((c) => c.potential_opportunity > 0)
  .sort((a, b) => b.potential_opportunity - a.potential_opportunity);

const candidateSuppliers = suppliers
  .filter(
    (s) =>
      (s.diverse || s.women_owned || s.minority_owned) &&
      s.esg_qualified &&
      s.risk_level !== RiskLevel.HIGH,
  )
  .map((s) => {
    const category = categories.find((c) => c.category === s.category);
    const gap = categoryGaps.find((c) => c.category === s.category);
    const categorySpend = category?.total_spend || 0;
    const concentration = categorySpend > 0 ? s.spend / categorySpend : 0;
    const certifications = [
      s.women_owned ? 'Women-Owned' : null,
      s.minority_owned ? 'Minority-Owned' : null,
      s.diverse ? 'Diverse' : null,
    ].filter(Boolean);
    const maxAdditional = Math.max(0, Math.round(categorySpend * maxCategoryShare - s.spend));

    return {
      supplier_id: s.supplier_id,
      supplier_name: s.supplier_name,
      category: s.category,
      current_spend: s.spend,
      esg_score: s.esg_score,
      risk_level: s.risk_level,
      women_owned: s.women_owned,
      minority_owned: s.minority_owned,
      diverse: s.diverse,
      certifications,
      category_share: concentration,
      underused: concentration < 0.15,
      shift_from: gap?.shift_from || null,
      max_additional_spend: maxAdditional,
      category_opportunity: gap?.potential_opportunity || 0,
    };
  })
  .filter((s) => s.max_additional_spend > 0 && s.category_opportunity > 0)
  .map((s) => ({ ...s, opportunity_score: scoreCandidate(s, data.metrics) }))
  .sort((a, b) => b.opportunity_score - a.opportunity_score || b.esg_score - a.esg_score);

const opportunities = {
  candidate_suppliers: candidateSuppliers.slice(0, 10),
  category_gaps: categoryGaps.slice(0, 6),
};

return [
  {
    json: {
      run_date: data.run_date,
      company_name: data.company_name,
      total_spend: data.total_spend,
      overall_status: data.overall_status,
      all_targets_met: data.all_targets_met,
      missed_targets: data.missed_targets,
      min_esg_score: minEsg,
      high_impact_threshold: data.high_impact_threshold,
      max_rebalance_pct: data.max_rebalance_pct,
      metrics: data.metrics,
      opportunities,
      ai_payload: {
        question: 'Where should we shift future procurement spend, and why?',
        overall_status: data.overall_status,
        missed_targets: data.missed_targets,
        total_spend: data.total_spend,
        metrics: data.metrics,
        min_esg_score: minEsg,
        max_category_share: maxCategoryShare,
        candidate_suppliers: opportunities.candidate_suppliers,
        category_gaps: opportunities.category_gaps,
        constraints: [
          'Primary objective: close the largest diversity spend gaps. ESG score and risk are constraints, not co-equal objectives.',
          'Recommend FROM → TO shifts, not generic "spend more".',
          'shift_from must be the listed non-diverse supplier in that category.',
          `Do not recommend ${RiskLevel.HIGH}-risk suppliers or ESG below min_esg_score.`,
          'recommended_shift must not exceed category potential_opportunity.',
          'recommended_shift must not exceed the candidate max_additional_spend (25% category cap).',
          'Prefer suppliers whose certifications help the largest missed gap.',
        ],
      },
    },
  },
];

const MetricStatus = Object.freeze({
  MET: 'MET',
  BELOW_TARGET: 'BELOW_TARGET',
});

const OverallStatus = Object.freeze({
  ON_TRACK: 'ON_TRACK',
  NEEDS_ATTENTION: 'NEEDS_ATTENTION',
  NO_DATA: 'NO_DATA',
});

const ReviewFlag = Object.freeze({
  NONE: 'NONE',
  HUMAN_REVIEW: 'HUMAN_REVIEW',
});

const Priority = Object.freeze({
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW',
});

const RiskLevel = Object.freeze({
  HIGH: 'High',
  MEDIUM: 'Medium',
  LOW: 'Low',
});

const GapKey = Object.freeze({
  DIVERSE: 'diverse',
  WOMEN: 'women_owned',
  MINORITY: 'minority_owned',
});

function asEnum(value, allowed, fallback) {
  const list = Array.isArray(allowed) ? allowed : Object.values(allowed);
  return list.includes(value) ? value : fallback;
}

const aiItem = $input.first().json;
const metricsItem = $('Calculate Spend Metrics').first().json;
const opportunityItem = $('Find Rebalancing Opportunities').first().json;

function extractText(payload) {
  if (payload == null) return '';
  if (typeof payload === 'string') return payload;
  if (typeof payload.output === 'string') return payload.output;
  if (typeof payload.text === 'string') return payload.text;
  if (payload.message && typeof payload.message.content === 'string') return payload.message.content;
  if (payload.output && typeof payload.output === 'object') return JSON.stringify(payload.output);
  return JSON.stringify(payload);
}

function parseJson(text) {
  const raw = String(text || '').trim();
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch (e) {
    const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (fenced) {
      try {
        return JSON.parse(fenced[1].trim());
      } catch (e2) {}
    }
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(raw.slice(start, end + 1));
      } catch (e3) {}
    }
  }
  return null;
}

function normalizePriority(value, reviewRequired) {
  const s = String(value || '').toUpperCase();
  return asEnum(s, Priority, reviewRequired ? Priority.HIGH : Priority.MEDIUM);
}

const parsed =
  typeof aiItem.output === 'object' && aiItem.output && !Array.isArray(aiItem.output)
    ? aiItem.output
    : parseJson(extractText(aiItem));

const candidates = opportunityItem.opportunities?.candidate_suppliers || [];
const categoryGaps = opportunityItem.opportunities?.category_gaps || [];
const candidateByName = {};
const candidateById = {};
for (const c of candidates) {
  candidateByName[String(c.supplier_name || '').toLowerCase()] = c;
  candidateById[String(c.supplier_id || '').toUpperCase()] = c;
}
const gapByCategory = {};
for (const g of categoryGaps) gapByCategory[g.category] = g;

const allSuppliers = metricsItem.supplier_spend || [];
function findSupplier(rec) {
  const id = String(rec.supplier_id || rec.supplierId || '').trim().toUpperCase();
  const name = String(rec.supplier || rec.supplier_name || rec.supplierName || '').trim().toLowerCase();
  return (
    candidateById[id] ||
    candidateByName[name] ||
    allSuppliers.find((s) => String(s.supplier_name || '').toLowerCase() === name)
  );
}

const minEsg = metricsItem.min_esg_score || 70;
const highImpact = metricsItem.high_impact_threshold || 500000;
const maxRebalancePct = Number(metricsItem.max_rebalance_pct || 0.15);
const rawRecs = Array.isArray(parsed?.recommendations) ? parsed.recommendations : [];
const validationNotes = [];
const cleaned = [];

if (!parsed) {
  validationNotes.push('AI output was not valid JSON; built fallback recommendations from opportunity candidates.');
}

const sourceRecs = rawRecs.length
  ? rawRecs
  : candidates.slice(0, 3).map((c) => {
      const gap = gapByCategory[c.category];
      const fallbackShift = Math.round(Math.min(150000, (gap?.potential_opportunity || 80000) * 0.4));
      return {
        supplier: c.supplier_name,
        supplier_id: c.supplier_id,
        category: c.category,
        shift_from: c.shift_from?.supplier_name || '',
        recommended_shift: fallbackShift,
        reason: `Underused ${c.certifications.join(', ')} supplier with ESG score ${c.esg_score}.`,
        priority: Priority.MEDIUM,
      };
    });

for (const rec of sourceRecs) {
  const supplier = findSupplier(rec);
  if (!supplier) {
    validationNotes.push(`Rejected unknown supplier: ${rec.supplier || rec.supplier_name || rec.supplier_id}`);
    continue;
  }

  if (supplier.risk_level === RiskLevel.HIGH) {
    validationNotes.push(`Rejected ${supplier.supplier_name}: risk level is ${RiskLevel.HIGH}.`);
    continue;
  }

  const esgScore = Number(supplier.esg_score || 0);
  if (esgScore < minEsg) {
    validationNotes.push(`Rejected ${supplier.supplier_name}: ESG score ${esgScore} is below ${minEsg}.`);
    continue;
  }

  if (!(supplier.diverse || supplier.women_owned || supplier.minority_owned)) {
    validationNotes.push(`Rejected ${supplier.supplier_name}: not a diverse / women-owned / minority-owned supplier.`);
    continue;
  }

  const gap = gapByCategory[supplier.category];
  const available = Number(gap?.potential_opportunity || 0);
  const concentrationCap = Number(supplier.max_additional_spend || 0);
  const nonDiverseCap = Math.round(Number(gap?.non_diverse_spend || 0) * 0.2);
  let shift = Number(rec.recommended_shift ?? rec.recommendedShift ?? rec.shift ?? 0);
  if (!Number.isFinite(shift) || shift <= 0) {
    validationNotes.push(`Rejected ${supplier.supplier_name}: recommended_shift is missing or invalid.`);
    continue;
  }

  if (available > 0 && shift > available) {
    validationNotes.push(`Capped ${supplier.supplier_name} from $${shift} to $${available} (category opportunity).`);
    shift = available;
  }
  if (nonDiverseCap > 0 && shift > nonDiverseCap) {
    validationNotes.push(`Capped ${supplier.supplier_name} from $${shift} to $${nonDiverseCap} (20% of non-diverse category spend).`);
    shift = nonDiverseCap;
  }
  if (concentrationCap > 0 && shift > concentrationCap) {
    validationNotes.push(`Capped ${supplier.supplier_name} from $${shift} to $${concentrationCap} (25% category concentration limit).`);
    shift = concentrationCap;
  }

  const shiftFrom =
    rec.shift_from ||
    rec.shiftFrom ||
    supplier.shift_from?.supplier_name ||
    gap?.shift_from?.supplier_name ||
    '';

  cleaned.push({
    supplier: supplier.supplier_name,
    supplier_id: supplier.supplier_id,
    category: supplier.category,
    shift_from: shiftFrom,
    recommended_shift: Math.round(shift),
    reason: rec.reason || rec.rationale || 'Qualified diverse supplier with capacity to absorb additional spend.',
    esg_score: esgScore,
    risk_level: asEnum(supplier.risk_level, RiskLevel, RiskLevel.MEDIUM),
    priority: normalizePriority(rec.priority || parsed?.priority, false),
  });
}

const bySupplier = {};
for (const rec of cleaned) {
  const existing = bySupplier[rec.supplier_id];
  if (!existing || rec.recommended_shift > existing.recommended_shift) {
    bySupplier[rec.supplier_id] = rec;
  }
}

const maxTotal = Math.round(Number(metricsItem.total_spend || 0) * maxRebalancePct);
let running = 0;
const unique = Object.values(bySupplier).sort((a, b) => b.recommended_shift - a.recommended_shift);
const capped = [];
for (const rec of unique) {
  if (running >= maxTotal) {
    validationNotes.push(`Dropped ${rec.supplier}: total rebalance cap of $${maxTotal} reached.`);
    continue;
  }
  const room = maxTotal - running;
  if (rec.recommended_shift > room) {
    validationNotes.push(`Capped ${rec.supplier} from $${rec.recommended_shift} to $${room} (total rebalance cap).`);
    rec.recommended_shift = room;
  }
  if (rec.recommended_shift <= 0) continue;
  running += rec.recommended_shift;
  capped.push(rec);
}

const maxShift = capped.reduce((m, r) => Math.max(m, r.recommended_shift), 0);
const reviewRequired = maxShift > highImpact;
const reviewFlag = reviewRequired ? ReviewFlag.HUMAN_REVIEW : ReviewFlag.NONE;
const aiPriority = normalizePriority(parsed?.priority, reviewRequired);

for (const rec of capped) {
  rec.priority = reviewRequired ? Priority.HIGH : rec.priority;
}

return [
  {
    json: {
      run_date: metricsItem.run_date,
      company_name: metricsItem.company_name,
      missed_targets: metricsItem.missed_targets,
      total_spend: metricsItem.total_spend,
      overall_status: asEnum(metricsItem.overall_status, OverallStatus, OverallStatus.NEEDS_ATTENTION),
      all_targets_met: metricsItem.all_targets_met,
      metrics: metricsItem.metrics,
      min_esg_score: minEsg,
      high_impact_threshold: highImpact,
      max_rebalance_pct: maxRebalancePct,
      ai_priority: aiPriority,
      recommendations: capped,
      review_required: reviewRequired,
      review_flag: reviewFlag,
      max_recommended_shift: maxShift,
      validation_notes: validationNotes,
    },
  },
];

const MetricStatus = Object.freeze({
  MET: 'MET',
  BELOW_TARGET: 'BELOW_TARGET',
});

const OverallStatus = Object.freeze({
  ON_TRACK: 'ON_TRACK',
  NEEDS_ATTENTION: 'NEEDS_ATTENTION',
  NO_DATA: 'NO_DATA',
});

const ReviewFlag = Object.freeze({
  NONE: 'NONE',
  HUMAN_REVIEW: 'HUMAN_REVIEW',
});

const Priority = Object.freeze({
  HIGH: 'HIGH',
  MEDIUM: 'MEDIUM',
  LOW: 'LOW',
});

const RiskLevel = Object.freeze({
  HIGH: 'High',
  MEDIUM: 'Medium',
  LOW: 'Low',
});

const GapKey = Object.freeze({
  DIVERSE: 'diverse',
  WOMEN: 'women_owned',
  MINORITY: 'minority_owned',
});

function asEnum(value, allowed, fallback) {
  const list = Array.isArray(allowed) ? allowed : Object.values(allowed);
  return list.includes(value) ? value : fallback;
}

const metricsItem = $('Calculate Spend Metrics').first().json;
const summaryItem = $input.first().json;
const NOTION_TEXT_LIMIT = 1900;

function extractText(payload) {
  if (payload == null) return '';
  if (typeof payload === 'string') return payload;
  if (typeof payload.output === 'string') return payload.output;
  if (typeof payload.text === 'string') return payload.text;
  if (payload.message && typeof payload.message.content === 'string') return payload.message.content;
  if (typeof payload.executive_summary === 'string') return payload.executive_summary;
  return '';
}

function money(n) {
  return `$${Number(n || 0).toLocaleString('en-US')}`;
}

function truncate(text, max) {
  const s = String(text || '').trim();
  if (s.length <= max) return s;
  return `${s.slice(0, max - 1).trim()}…`;
}

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

let recommendations = [];
let reviewRequired = false;
let reviewFlag = ReviewFlag.NONE;
let validationNotes = [];
let aiPriority = Priority.MEDIUM;
try {
  const validated = $('Validate Recommendations').first().json;
  recommendations = validated.recommendations || [];
  reviewRequired = !!validated.review_required;
  reviewFlag = asEnum(
    validated.review_flag,
    ReviewFlag,
    reviewRequired ? ReviewFlag.HUMAN_REVIEW : ReviewFlag.NONE,
  );
  validationNotes = validated.validation_notes || [];
  aiPriority = asEnum(validated.ai_priority, Priority, Priority.MEDIUM);
} catch (e) {
  recommendations = [];
  reviewRequired = false;
  reviewFlag = ReviewFlag.NONE;
}

let reportEmail = 'user@example.com';
let companyName = metricsItem.company_name || 'Your Company';
try {
  const cfg = $('Set Config').first().json;
  reportEmail = String(cfg.report_email || reportEmail);
  companyName = String(cfg.company_name || companyName);
} catch (e) {}

const m = metricsItem.metrics;
for (const key of [GapKey.DIVERSE, GapKey.WOMEN, GapKey.MINORITY, 'esg']) {
  m[key].status = asEnum(m[key].status, MetricStatus, MetricStatus.BELOW_TARGET);
}

const overallStatus = asEnum(metricsItem.overall_status, OverallStatus, OverallStatus.NEEDS_ATTENTION);
const priority = reviewRequired ? Priority.HIGH : asEnum(aiPriority, Priority, Priority.MEDIUM);

const actions = recommendations.map((r, i) => {
  const from = r.shift_from ? ` from ${r.shift_from}` : '';
  return `${i + 1}. Shift ${money(r.recommended_shift)} of ${r.category} spend${from} to ${r.supplier} — ${r.reason}`;
});
const recommendedActions = actions.length
  ? actions.join('\n')
  : overallStatus === OverallStatus.ON_TRACK
    ? 'No rebalancing required. Maintain the current qualified supplier mix.'
    : overallStatus === OverallStatus.NO_DATA
      ? 'No qualifying procurement spend was found for this run.'
      : 'No validated supplier shifts this run. Review opportunity candidates manually.';

function fallbackSummary() {
  const lines = [
    'Supplier Diversity & ESG Summary',
    `Company: ${companyName}`,
    `Overall Status: ${overallStatus}`,
    `Period: ${metricsItem.period}`,
    `Total Procurement Spend: ${money(metricsItem.total_spend)}`,
    '',
    `Diverse Supplier Spend: ${m.diverse.actual_pct_display}   Target: ${m.diverse.target_pct_display}   Status: ${m.diverse.status}`,
    `Women-Owned Spend: ${m.women_owned.actual_pct_display}   Target: ${m.women_owned.target_pct_display}   Status: ${m.women_owned.status}`,
    `Minority-Owned Spend: ${m.minority_owned.actual_pct_display}   Target: ${m.minority_owned.target_pct_display}   Status: ${m.minority_owned.status}`,
    `ESG Qualified Spend: ${m.esg.actual_pct_display}   Target: ${m.esg.target_pct_display}   Status: ${m.esg.status}`,
    '',
    'Key Finding:',
    overallStatus === OverallStatus.NO_DATA
      ? 'No qualifying procurement spend was found for this run.'
      : overallStatus === OverallStatus.ON_TRACK
        ? 'All configured diversity and ESG spend targets are met.'
        : 'One or more spend targets are below plan. See recommended actions.',
    '',
    'Recommended Action:',
    recommendedActions,
  ];
  if (reviewFlag === ReviewFlag.HUMAN_REVIEW) {
    lines.push('', 'Human review required for high-impact spend shifts.');
  }
  return lines.join('\n');
}

let executiveSummary = extractText(summaryItem).trim() || fallbackSummary();
executiveSummary = truncate(executiveSummary, NOTION_TEXT_LIMIT);
const recommendedActionsOut = truncate(recommendedActions, NOTION_TEXT_LIMIT);

const subjectPrefix = reviewFlag === ReviewFlag.HUMAN_REVIEW ? ReviewFlag.HUMAN_REVIEW : overallStatus;
const emailSubject = `[${subjectPrefix}] ${companyName} — Diversity & ESG — ${metricsItem.run_date}`;
const notionTitle = truncate(`${metricsItem.run_date} — ${overallStatus} — ${companyName}`, 100);

const recHtml = recommendations.length
  ? `<ol>${recommendations
      .map((r) => {
        const from = r.shift_from ? ` from <b>${escapeHtml(r.shift_from)}</b>` : '';
        return `<li>Shift ${money(r.recommended_shift)} of <b>${escapeHtml(r.category)}</b> spend${from} to <b>${escapeHtml(r.supplier)}</b> — ${escapeHtml(r.reason)}</li>`;
      })
      .join('')}</ol>`
  : `<p>${escapeHtml(recommendedActionsOut)}</p>`;

const statusRow = (label, metric) =>
  `<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">${label}</td><td style="padding:6px 12px;border-bottom:1px solid #eee">${metric.actual_pct_display}</td><td style="padding:6px 12px;border-bottom:1px solid #eee">${metric.target_pct_display}</td><td style="padding:6px 12px;border-bottom:1px solid #eee">${metric.status}</td></tr>`;

const emailBody = `
<div style="font-family:Arial,sans-serif;color:#111;max-width:720px">
  <h2 style="margin-bottom:4px">${escapeHtml(companyName)} — Supplier Diversity &amp; ESG Briefing</h2>
  <p style="margin-top:0;color:#555">${escapeHtml(metricsItem.period)} · ${escapeHtml(metricsItem.run_date)} · Status: <b>${overallStatus}</b> · Priority: <b>${priority}</b> · Review: <b>${reviewFlag}</b></p>
  <p>Total procurement spend: <b>${money(metricsItem.total_spend)}</b></p>
  <table style="border-collapse:collapse;width:100%;font-size:14px">
    <thead><tr style="text-align:left;background:#f6f6f6"><th style="padding:6px 12px">Metric</th><th style="padding:6px 12px">Actual</th><th style="padding:6px 12px">Target</th><th style="padding:6px 12px">Status</th></tr></thead>
    <tbody>
      ${statusRow('Diverse spend', m.diverse)}
      ${statusRow('Women-owned spend', m.women_owned)}
      ${statusRow('Minority-owned spend', m.minority_owned)}
      ${statusRow('ESG-qualified spend', m.esg)}
    </tbody>
  </table>
  <h3>Where to shift future spend</h3>
  ${recHtml}
  <h3>Executive summary</h3>
  <pre style="white-space:pre-wrap;font-family:Arial,sans-serif;font-size:14px;line-height:1.45">${escapeHtml(executiveSummary)}</pre>
</div>
`.trim();

return [
  {
    json: {
      company_name: companyName,
      report_email: reportEmail,
      notion_title: notionTitle,
      email_subject: emailSubject,
      email_body: emailBody,
      run_date: metricsItem.run_date,
      period: metricsItem.period,
      total_spend: metricsItem.total_spend,
      overall_status: overallStatus,
      priority,
      review_required: reviewRequired,
      review_flag: reviewFlag,
      diverse_actual: m.diverse.actual_pct_points,
      diverse_target: m.diverse.target_pct_points,
      diverse_status: m.diverse.status,
      women_owned_actual: m.women_owned.actual_pct_points,
      women_owned_target: m.women_owned.target_pct_points,
      women_owned_status: m.women_owned.status,
      minority_owned_actual: m.minority_owned.actual_pct_points,
      minority_owned_target: m.minority_owned.target_pct_points,
      minority_owned_status: m.minority_owned.status,
      esg_actual: m.esg.actual_pct_points,
      esg_target: m.esg.target_pct_points,
      esg_status: m.esg.status,
      executive_summary: executiveSummary,
      recommended_actions: recommendedActionsOut,
      recommendations,
      recommendations_json: JSON.stringify(recommendations),
      validation_notes: validationNotes,
      unmatched_count: metricsItem.unmatched_count || 0,
    },
  },
];
